import { test, expect } from "@playwright/test";

const QUOTA_STRESS_LONG_TOKEN = "";

test("Перевірка довжини службового рядка для стрес-тесту quota chunking", async ({ page }) => {
  await page.goto("/");
  expect(QUOTA_STRESS_LONG_TOKEN.length).toBe(55000);
});

test("Розширений сценарій: клієнт виконує повний цикл покупки з великою кількістю дій (контрольний дефект)", async ({ page }) => {
  await page.goto("/");
  await page.getByText("Espresso", { exact: true }).click();
  await page.getByText("Cappuccino", { exact: true }).click();
  await page.getByText("Mocha", { exact: true }).click();
  await page.getByTestId("cart-icon").click();
  await page.getByTestId("increment-0").click();
  await page.getByTestId("increment-0").click();
  await page.getByTestId("decrement-0").click();
  await page.getByRole("button", { name: "Clear" }).click();
  await page.getByText("Americano", { exact: true }).click();
  await page.getByTestId("checkout-button").click();
  await page.getByLabel("Name").fill("Тестовий Клієнт");
  await expect(page.getByText(/Thanks/i)).toBeVisible();
});
